 '<div class="grid split-grid"><section class="panel"><h3>Learning journey</h3><p class="panel-sub">17 connected tracks · Foundation to production</p>'+CURRICULUM.slice(0,7).map(t=>'<div class="progress-row"><span>'+t.num+' · '+esc(t.title)+'</span><span>'+(trackDone(t)?"COMPLETE":"UP NEXT")+'</span></div>'+progressBar(trackDone(t)?100:0)).join("")+'<div style="margin-top:14px"><button class="btn secondary" data-go="roadmap">View all tracks →</button></div></section><section class="panel"><h3>Practice workspace</h3><p class="panel-sub">Apply ideas, not just memorize terms.</p><div class="quick-actions"><button class="quick-action" data-go="terminal"><b>$_ Terminal</b><small>Practice safe command workflows</small></button><button class="quick-action" data-go="code"><b>⌁ Code repair</b><small>Fix broken engineering files</small></button><button class="quick-action" data-go="projects"><b>◫ Projects</b><small>Build progressive portfolio work</small></button></div></section></div>'+
 sectionHead("START HERE","Core roadmap tracks","Open a track to learn, answer its questions and run its practical lab.")+
 '<div class="grid roadmap-grid">'+CURRICULUM.slice(0,6).map(trackCard).join("")+'</div>'+
 sectionHead("YOUR PERFORMANCE","Recent approach reviews","Scores are a coaching signal based on the reasoning you submit, not a formal certification.")+
 (recent.length?'<div class="grid senior-grid">'+recent.map(r=>'<article class="senior-card"><span class="spark">✦</span><h3>'+esc(r.label)+'</h3><p>'+esc(r.summary)+'</p><div class="rating">APPROACH SCORE · '+r.score+'/100</div></article>').join("")+'</div>':'<div class="empty">No scored practice yet. Try the Incident Simulator and explain your investigation approach.</div>');
