const PROJECT_GUIDES={"linuxops":[["How do you ensure the cleanup script cannot delete arbitrary paths?","How will a non-root service account run diagnostics safely?","What evidence will prove the service is healthy?"],[["Linux man-pages","https://man7.org/linux/man-pages/"],["systemd manual","https://www.freedesktop.org/software/systemd/man/"]]],"gitpipeline":[["What should run on pull requests and what belongs only in a protected release?","How do you prove an artifact maps to one commit?","Which permissions does each job actually need?"],[["GitHub Actions","https://docs.github.com/actions"],["Maven lifecycle","https://maven.apache.org/guides/introduction/introduction-to-the-lifecycle.html"]]],"containerapp":[["How do you prove the final image runs as non-root?","What belongs in build stage versus runtime stage?","How will you roll back to a known image digest?"],[["Docker build best practices","https://docs.docker.com/build/building/best-practices/"],["Docker Compose","https://docs.docker.com/compose/"]]],"terraformnetwork":[["How will you avoid destructive changes during a Terraform plan?","How will remote state be protected and recovered?","What module inputs and outputs are required?"],[["Terraform language","https://developer.hashicorp.com/terraform/language"],["AWS VPC","https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html"]]],"cloudplatform":[["Which resources are public and which remain private?","How will CI and runtime identities be separated?","What are the recurring cost drivers?"],[["AWS Well-Architected","https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"],["AWS Pricing Calculator","https://calculator.aws/"]]],"k8sdelivery":[["How do readiness, liveness and startup probes differ?","How will you diagnose a Service with no endpoints?","What is your rollout and rollback strategy?"],[["Kubernetes docs","https://kubernetes.io/docs/concepts/"],["Helm docs","https://helm.sh/docs/"]]],"secureops":[["How do you connect an SBOM to the exact image digest?","Which SLO alerts are actionable?","What evidence proves rollback works?"],[["SLSA framework","https://slsa.dev/"],["OpenTelemetry","https://opentelemetry.io/docs/"]]],"aiplatform":[["How will retrieval enforce access control before context is supplied to the model?","How will you test prompt injection and hallucination?","Which actions must require human approval?"],[["NIST AI RMF","https://www.nist.gov/itl/ai-risk-management-framework"],["OWASP GenAI Security","https://genai.owasp.org/"]]]};
